async function killPat(pat) {
  const end = deadline - 20_000;
  for (let i = 0; i < 4 && Date.now() < end; i++) {
    const s = sdk.getState();
    const npc = s.nearbyNpcs.filter(n => pat.test(n.name) && !n.unreachable).sort((a,b)=>a.distance-b.distance)[0];
    if (!npc) return 'none';
    try { await bot.attack(npc); } catch (e) {}
    for (let t = 0; t < 12 && Date.now() < end; t++) {
      await new Promise(r => setTimeout(r, 1000));
      if (!sdk.getState().nearbyNpcs.find(n => n.index === npc.index)) return `${npc.name} L${npc.combatLevel} KILLED`;
    }
  }
  return 'timeout';
}
